import{_ as e,o as t,c as a,ag as r}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/board/index-overview.png",n="/docs/images/board/index-dock-mobile.png",b=JSON.parse('{"title":"Board","description":"A board is an infinite canvas where you arrange sticky notes, shapes, drawings, and images with your team.","frontmatter":{"title":"Board","description":"A board is an infinite canvas where you arrange sticky notes, shapes, drawings, and images with your team.","type":"overview"},"headers":[],"relativePath":"board/index.md","filePath":"board/index.md"}'),i={name:"board/index.md"};function d(h,o,l,c,g,p){return t(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="board" tabindex="-1">Board <a class="header-anchor" href="#board" aria-label="Permalink to &quot;Board&quot;">​</a></h1><p>A board is an infinite canvas where you arrange sticky notes, shapes, drawings, and images with your team.</p><p>Use it to:</p><ul><li>Brainstorm with sticky notes, then group them into titled sections</li><li>Sketch diagrams with shapes, connectors, and a marker</li><li>Run a retro or workshop with a shared timer, dot voting, and stamps</li></ul><p><img src="'+s+'" alt="Retro board with the top toolbar, the tool dock at the bottom, the minimap, and the Download button"></p><p>The board has two toolbars. The <strong>tool dock</strong> along the bottom holds everything you add: select, sticky notes, text, shapes, lines, the marker, sections, images, stamps, and comments. The <strong>top toolbar</strong> holds undo and redo, <strong>Zoom ▾</strong>, <strong>Grid ▾</strong>, <strong>Sections</strong> (the list icon), and the session tools: <strong>Timer</strong>, <strong>Start voting…</strong>, <strong>Spotlight me</strong>, and <strong>Laser pointer</strong>. When you select something, the top toolbar also shows controls for it.</p><p>In dark mode, the board&#39;s background is dimmed rather than dark, so everyone sees the same colors on the board.</p><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><ol><li>In your workspace, click <strong>New</strong>, then select <strong>New board</strong>. A board named <strong>Untitled board</strong> opens. To start from a ready-made layout instead, select <strong>New from template</strong>. See <a href="/docs/collaborate/templates.html">Templates</a>.</li><li>Press <code>S</code> to add a sticky note, type your idea, and press <code>Tab</code> to add the next one. See <a href="/docs/board/stickies-shapes-connectors.html">Stickies, shapes, and connectors</a>.</li><li>Click <strong>Share</strong> in the top right to invite your team. See <a href="/docs/collaborate/share.html">Share a document</a>.</li></ol><p>Click the board&#39;s title in the header to rename it. Changes save automatically.</p><h2 id="move-around-a-board" tabindex="-1">Move around a board <a class="header-anchor" href="#move-around-a-board" aria-label="Permalink to &quot;Move around a board&quot;">​</a></h2><ul><li><strong>Pan</strong>: scroll or swipe with two fingers on a trackpad. Hold <code>Shift</code> and scroll to pan sideways. To pan by dragging, hold <code>Space</code> and drag, drag with the middle mouse button, or pick the <strong>Hand</strong> tool (<code>H</code>) in the dock.</li><li><strong>Zoom</strong>: hold <code>⌘</code> / <code>Ctrl</code> and scroll, or pinch on a trackpad. The point under the pointer stays in place.</li><li><strong>Zoom to a level</strong>: open <strong>Zoom ▾</strong> in the top toolbar and pick <strong>Fit</strong>, 10%, 25%, 50%, 100%, 200%, 400%, or 800%. <strong>Fit</strong> frames everything on the board. Zoom ranges from 10% to 800%.</li><li><strong>Use the minimap</strong>: the minimap in the bottom-right corner shows the whole board. Drag inside it to move to another area. Click <strong>Map</strong> to hide or show it.</li><li><strong>Jump to a section</strong>: click <strong>Sections</strong> in the top toolbar and pick a section.</li><li><strong>Frame everything</strong>: right-click empty canvas and select <strong>Fit to content</strong>, or press <code>Shift+1</code>.</li><li><strong>Find text</strong>: press <code>⌘+F</code> / <code>Ctrl+F</code>, type, and press <code>Enter</code> for the next match or <code>Shift+Enter</code> for the previous one. Find searches sticky notes, shapes, text boxes, and connector labels.</li></ul><p>A board opens framed on its content. For every zoom and navigation key, see <a href="/docs/board/keyboard-shortcuts.html#navigation">Keyboard shortcuts</a>.</p><h3 id="change-the-grid" tabindex="-1">Change the grid <a class="header-anchor" href="#change-the-grid" aria-label="Permalink to &quot;Change the grid&quot;">​</a></h3><p>Open <strong>Grid ▾</strong> and pick <strong>None</strong>, <strong>Dot grid</strong> (the default), or <strong>Line grid</strong>. <strong>Snap to grid</strong> (on by default) lines up moved and resized items on the grid, even when the grid is hidden. These are your own settings, saved in this browser. Teammates keep theirs.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><p><strong>Add and arrange content</strong></p><ul><li><a href="/docs/board/stickies-shapes-connectors.html#add-a-sticky-note">Add and style sticky notes</a></li><li><a href="/docs/board/stickies-shapes-connectors.html#add-a-shape">Add shapes, text, and images</a></li><li><a href="/docs/board/stickies-shapes-connectors.html#connect-items">Connect items with lines and arrows</a></li><li><a href="/docs/board/stickies-shapes-connectors.html#arrange-items">Align, group, and tidy up items</a></li></ul><p><strong>Sketch</strong></p><ul><li><a href="/docs/board/draw.html#draw-with-the-marker-or-highlighter">Draw with the marker or highlighter</a></li><li><a href="/docs/board/draw.html#erase-strokes">Erase strokes and point with the laser</a></li><li><a href="/docs/board/draw.html#select-with-the-lasso">Select with the lasso</a></li></ul><p><strong>Organize</strong></p><ul><li><a href="/docs/board/sections.html">Group ideas into sections</a></li><li><a href="/docs/board/sections.html#hide-the-contents-of-a-section">Hide or lock a section</a></li></ul><p><strong>Run a session</strong></p><ul><li><a href="/docs/board/facilitate-a-session.html#start-a-shared-timer">Time-box with a shared timer</a></li><li><a href="/docs/board/facilitate-a-session.html#run-a-dot-vote">Run a dot vote</a></li><li><a href="/docs/board/facilitate-a-session.html#follow-a-teammate">Follow a teammate or spotlight your view</a></li><li><a href="/docs/board/facilitate-a-session.html#comment-on-a-board">Comment on a board</a></li></ul><p><strong>Share the result</strong></p><ul><li><a href="/docs/board/export-and-import.html#download-a-board">Download a board as PNG or PDF</a></li><li><a href="/docs/board/export-and-import.html#import-a-miro-board">Import a Miro board</a></li><li><a href="/docs/collaborate/version-history.html">Browse and restore earlier versions</a></li></ul><h2 id="what-viewers-can-do" tabindex="-1">What viewers can do <a class="header-anchor" href="#what-viewers-can-do" aria-label="Permalink to &quot;What viewers can do&quot;">​</a></h2><p>Someone with a viewer link sees the board update live, along with everyone&#39;s cursors and the timer. They can pan by dragging, zoom, find text, and download the board. They can&#39;t add or change anything, vote, or comment, and they don&#39;t see the toolbars.</p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>On a phone, drag empty canvas with one finger to pan and pinch to zoom. Touch and hold empty canvas to open the menu for adding a sticky note or section. The dock keeps <strong>Select</strong>, <strong>Sticky note</strong>, <strong>Text box</strong>, <strong>Shape</strong>, and <strong>Marker</strong>, and moves the other tools into <strong>More tools</strong> (the ⋯ button). The session tools fold into one <strong>Facilitate</strong> button in the top toolbar. The minimap starts hidden. See <a href="/docs/start/phone.html">Use Wafflebase on a phone</a>.</p><p><img src="'+n+'" alt="Board on a phone with the compact tool dock and the More tools popover open above it"></p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="/docs/board/keyboard-shortcuts.html">Keyboard shortcuts</a>: every board key, matching the in-app list</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/docs/board/run-a-retro.html">Run a retro on a board</a> to learn the core tools in about 15 minutes.</li><li><a href="/docs/board/stickies-shapes-connectors.html">Stickies, shapes, and connectors</a> to add and style content.</li><li><a href="/docs/developers/cli/slides-and-board.html">CLI: slides and boards</a> to add stickies and sections from a script.</li></ul>',35)])])}const u=e(i,[["render",d]]);export{b as __pageData,u as default};
